const DISCIPLINES=[{name:'Neurology',icon:'◉',desc:'Stroke, brain injury, SCI, MS and neurological rehabilitation',count:1},{name:'Musculoskeletal',icon:'✣',desc:'Spine, joints, pain and movement conditions',count:1},{name:'Paediatrics',icon:'♧',desc:'Child development and paediatric rehabilitation',count:1},{name:'Cardiorespiratory',icon:'♡',desc:'Acute respiratory care, pulmonary and cardiac rehabilitation',count:3},{name:'Orthopaedics',icon:'⌁',desc:'Fractures, joint replacement and post-operative rehabilitation',count:3},{name:'Burns',icon:'♨',desc:'Burn rehabilitation, positioning, mobility and scar management',count:2},{name:"Women’s health",icon:'✿',desc:'Pelvic health, pregnancy, postpartum and continence',count:0},{name:'Geriatrics and falls',icon:'⌂',desc:'Frailty, falls prevention, mobility and healthy ageing',count:0},{name:'Critical care and transitions',icon:'＋',desc:'ICU, prehabilitation and post-hospital rehabilitation',count:0},{name:'Oncology',icon:'✚',desc:'Cancer rehabilitation, fatigue and exercise',count:0},{name:'Amputee rehabilitation',icon:'↗',desc:'Pre-prosthetic, prosthetic and lifelong rehabilitation',count:0},{name:'Vestibular',icon:'◌',desc:'Dizziness, balance and vestibular rehabilitation',count:0}];
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
let currentView='home',currentDiscipline='All',currentId=null,toastTimer=null,installPrompt=null;
let bookmarks=new Set();try{bookmarks=new Set(JSON.parse(localStorage.getItem('pg-bookmarks')||'[]'))}catch(e){}
function saveBookmarks(){localStorage.setItem('pg-bookmarks',JSON.stringify([...bookmarks]));updateBookmarkCount()}
function updateBookmarkCount(){$('#bookmarkCount').textContent=bookmarks.size}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function card(g){const saved=bookmarks.has(g.id);return `<article class="guideline-card" data-open="${g.id}" tabindex="0" role="button" aria-label="Open ${esc(g.title)}"><div class="card-topline"><span class="tag">${esc(g.discipline)}</span><button class="bookmark-mini ${saved?'saved':''}" data-bookmark="${g.id}" aria-label="${saved?'Remove bookmark':'Save bookmark'}" title="${saved?'Remove bookmark':'Save bookmark'}">${saved?'★':'☆'}</button></div><h3>${esc(g.title)}</h3><p>${esc(g.summary)}</p><div class="card-meta"><span>${esc(g.source)} · ${esc(g.population)}</span><strong>Open guideline →</strong></div></article>`}
function renderDisciplineCards(){ $('#disciplineCards').innerHTML=DISCIPLINES.map(d=>d.count?`<button class="discipline-card" data-discipline="${d.name}"><span class="card-arrow">↗</span><span class="discipline-icon">${d.icon}</span><strong>${d.name}</strong><small>${d.desc}</small><span class="tag">${d.count} live summary</span></button>`:`<article class="discipline-card planned-card"><span class="card-arrow">＋</span><span class="discipline-icon">${d.icon}</span><strong>${d.name}</strong><small>${d.desc}</small><span class="tag">Planned coverage</span></article>`).join('');}
function renderHome(){$('#featuredList').innerHTML=GUIDELINES.map(card).join('');$('#guidelineTotal').textContent=GUIDELINES.length;}
function showView(view){currentView=view;$$('.view').forEach(v=>v.classList.add('hidden'));const target=$(`#${view}View`);if(target)target.classList.remove('hidden');$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
function openLibrary(discipline='All'){currentDiscipline=discipline;$('#libraryTitle').textContent=discipline==='All'?'All guidelines':`${discipline} guidelines`;$('#disciplineFilter').value=discipline;$('#searchInput').value='';$('#populationFilter').value='All';renderResults();showView('library')}
function renderResults(){const q=$('#searchInput').value.trim().toLowerCase(),d=$('#disciplineFilter').value,p=$('#populationFilter').value;const results=GUIDELINES.filter(g=>(d==='All'||g.discipline===d)&&(p==='All'||g.population===p)&&(!q||[g.title,g.discipline,g.population,g.condition,g.summary,g.source,...g.keywords].join(' ').toLowerCase().includes(q)));$('#resultsCount').textContent=`${results.length} ${results.length===1?'guideline':'guidelines'}`;$('#guidelineResults').innerHTML=results.length?results.map(card).join(''):`<div class="empty-state"><strong>No matching guidelines found</strong>Try another keyword or clear the filters. More clinical topics will be added in future releases.</div>`;}
function openDetail(id){const g=GUIDELINES.find(x=>x.id===id);if(!g)return;currentId=id;const saved=bookmarks.has(id);const recs=g.management.map(([h,p])=>`<div class="recommendation"><strong>${esc(h)}</strong><p>${esc(p)}</p></div>`).join('');const refs=g.references.map((r,i)=>`<div class="source-item"><strong>${i+1}. ${esc(r.name)}</strong><small>${esc(r.detail)}</small><a href="${esc(r.url)}" target="_blank" rel="noopener">Open original source ↗</a></div>`).join('');$('#guidelineDetail').innerHTML=`<div class="detail-header"><span class="eyebrow">${esc(g.discipline.toUpperCase())} · CLINICAL GUIDELINE SUMMARY</span><h1>${esc(g.title)}</h1><p>${esc(g.summary)}</p><div class="detail-meta"><span>${esc(g.source)}</span><span>${esc(g.population)}</span><span>Source date: ${esc(g.updated)}</span></div><div class="detail-actions"><button data-bookmark="${g.id}">${saved?'★ Saved to bookmarks':'☆ Save bookmark'}</button><button id="shareGuideline">↗ Share reference</button></div></div><div class="detail-content"><article class="detail-main"><h2>Clinical overview</h2><p>${esc(g.overview)}</p><h3>Assessment considerations</h3><ul>${g.assessment.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Management principles</h3>${recs}<h3>Red flags and referral considerations</h3><div class="recommendation caution"><strong>Safety first</strong><ul>${g.redFlags.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><h3>Suggested outcome measures</h3><p>Choose measures appropriate to the person's age, goals, communication, abilities and local validation. Check licensing and training requirements before use.</p><ul>${g.measures.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Evidence grading and interpretation</h3><p>${esc(g.grading)}</p><h3>References and original guidance</h3>${refs}<p class="muted"><small>Access date for this app record: 16 November 2026. Always check the live source for amendments and superseded recommendations.</small></p></article><aside class="detail-aside"><h3>At a glance</h3><div class="aside-note"><strong>Discipline</strong>${esc(g.discipline)}</div><div class="aside-note"><strong>Population</strong>${esc(g.population)}</div><div class="aside-note"><strong>Primary source</strong>${esc(g.source)}</div><div class="aside-note"><strong>Source review / update</strong>${esc(g.updated)}</div><div class="aside-note"><strong>Content status</strong>Concise starter summary; not independently peer reviewed yet.</div><div class="aside-note"><strong>Clinical reminder</strong>Apply local pathways, scope of practice and individual clinical judgement.</div></aside></div>`;showView('detail');$('#shareGuideline').addEventListener('click',()=>shareGuideline(g));}
function shareGuideline(g){const url=location.href.split('#')[0]+`#guideline=${g.id}`;if(navigator.share)navigator.share({title:g.title,text:'PhysioGuidelines clinical reference',url}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(url).then(()=>toast('Guideline link copied'));else toast('Copy the page address to share this guideline');}
function renderBookmarks(){const list=GUIDELINES.filter(g=>bookmarks.has(g.id));$('#bookmarkResults').innerHTML=list.length?list.map(card).join(''):`<div class="empty-state"><strong>No saved guidelines yet</strong>Use the star on any guideline to add it to your personal library. Bookmarks stay on this device.</div>`;}
function toggleBookmark(id){if(bookmarks.has(id)){bookmarks.delete(id);toast('Removed from bookmarks')}else{bookmarks.add(id);toast('Saved to bookmarks')}saveBookmarks();renderHome();if(currentView==='library')renderResults();if(currentView==='bookmarks')renderBookmarks();if(currentView==='detail'&&currentId===id)openDetail(id);}
document.addEventListener('click',e=>{const bm=e.target.closest('[data-bookmark]');if(bm){e.stopPropagation();toggleBookmark(bm.dataset.bookmark);return}const open=e.target.closest('[data-open]');if(open){openDetail(open.dataset.open);return}const go=e.target.closest('[data-go]');if(go){openLibrary();return}const disc=e.target.closest('[data-discipline]');if(disc){openLibrary(disc.dataset.discipline);return}const coming=e.target.closest('[data-coming]');if(coming){toast(`${coming.dataset.coming} content is planned for a future release`);return}const nav=e.target.closest('[data-view]');if(nav){if(nav.dataset.view==='library')openLibrary();else if(nav.dataset.view==='bookmarks'){renderBookmarks();showView('bookmarks')}else showView(nav.dataset.view);return}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open]')){e.preventDefault();openDetail(e.target.dataset.open)}});
$('#searchInput').addEventListener('input',renderResults);$('#disciplineFilter').addEventListener('change',renderResults);$('#populationFilter').addEventListener('change',renderResults);$('#clearFilters').addEventListener('click',()=>{$('#searchInput').value='';$('#disciplineFilter').value='All';$('#populationFilter').value='All';$('#libraryTitle').textContent='All guidelines';renderResults()});$('#backToLibrary').addEventListener('click',()=>openLibrary());$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#aboutLink').addEventListener('click',e=>{e.preventDefault();$('#aboutDialog').showModal()});$('#closeAbout').addEventListener('click',()=>$('#aboutDialog').close());$('#closeAbout2').addEventListener('click',()=>$('#aboutDialog').close());
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').addEventListener('click',async()=>{if(!installPrompt){toast('Use your browser menu and choose “Install app” or “Add to Home Screen”');return}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installBtn').classList.add('hidden')});window.addEventListener('appinstalled',()=>toast('PhysioGuidelines installed'));
if('serviceWorker'in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}
updateBookmarkCount();renderDisciplineCards();renderHome();
if(location.hash.startsWith('#guideline=')){const id=decodeURIComponent(location.hash.split('=')[1]);if(GUIDELINES.some(g=>g.id===id))openDetail(id)}
